RED.comms = (function() {

    var errornotification = null;
    var clearErrorTimer = null;
    var connectCountdownTimer = null;
    var connectCountdown = 10;
    var subscriptions = {};
    var ws;
    var pendingAuth = false;
    var reconnectAttempts = 0;
    var active = false;
    var connected = false;
    var session = null;
    var loggingOut = false;

    // Fired once the connection is established and authenticated
    var connectionOpenedHandlers = [];
    // Fired when the user logs out of the editor
    var logoutHandlers = [];

    function notifyConnectionOpened() {
        connected = true;
        connectionOpenedHandlers.slice().forEach(function(handler) {
            try {
                handler(session);
            } catch(err) {
                console.warn(err);
            }
        });
        RED.events.emit("comms:connected",session);
    }

    function notifyLogout() {
        logoutHandlers.slice().forEach(function(handler) {
            try {
                handler();
            } catch(err) {
                console.warn(err);
            }
        });
        RED.events.emit("comms:logout");
    }

    function connectWS() {
        active = true;
        session = null;
        var wspath;

        if (RED.settings.apiRootUrl) {
            var m = /^(https?):\/\/(.*)$/.exec(RED.settings.apiRootUrl);
            if (m) {
                console.log(m);
                wspath = "ws"+(m[1]==="https"?"s":"")+"://"+m[2]+"comms";
            }
        } else {
            var path = location.hostname;
            var port = location.port;
            if (port.length !== 0) {
                path = path+":"+port;
            }
            path = path+document.location.pathname;
            path = path+(path.slice(-1) == "/"?"":"/")+"comms";
            wspath = "ws"+(document.location.protocol=="https:"?"s":"")+"://"+path;
        }

        var auth_tokens = RED.settings.get("auth-tokens");
        pendingAuth = (auth_tokens!=null);

        function completeConnection() {
            for (var t in subscriptions) {
                if (subscriptions.hasOwnProperty(t)) {
                    ws.send(JSON.stringify({subscribe:t}));
                }
            }
            // Request this connection's session id, then notify listeners
            ws.send(JSON.stringify({session:null}));
        }

        ws = new WebSocket(wspath);
        ws.onopen = function() {
            reconnectAttempts = 0;
            loggingOut = false;
            if (errornotification) {
                clearErrorTimer = setTimeout(function() {
                    errornotification.close();
                    errornotification = null;
                },1000);
            }
            if (pendingAuth) {
                ws.send(JSON.stringify({auth:auth_tokens.access_token}));
            } else {
                completeConnection();
            }
        }
        ws.onmessage = function(event) {
            var message = JSON.parse(event.data);
            if (message.auth) {
                if (pendingAuth) {
                    if (message.auth === "ok") {
                        pendingAuth = false;
                        completeConnection();
                    } else if (message.auth === "fail") {
                        // anything else is an error...
                        active = false;
                        RED.user.login({updateMenu:true},function() {
                            connectWS();
                        })
                    }
                } else if (message.auth === "fail") {
                    if (loggingOut) {
                        // The failure is due to us logging out. Ignore it;
                        // the close handler reconnects anonymously.
                        return;
                    }
                    // Our current session has expired
                    active = false;
                    RED.user.login({updateMenu:true},function() {
                        connectWS();
                    })
                } else if (message.auth === "ok") {
                    // The connection has been re-authenticated following a
                    // login without a page refresh.
                    RED.events.emit("comms:reauthenticated",session);
                }
            } else if (message.hasOwnProperty("session")) {
                session = message.session;
                if (!connected) {
                    notifyConnectionOpened();
                }
            } else {
                // Otherwise, 'message' is an array of actual comms messages
                for (var m = 0; m < message.length; m++) {
                    var msg = message[m];
                    if (msg.topic) {
                        for (var t in subscriptions) {
                            if (subscriptions.hasOwnProperty(t)) {
                                var re = new RegExp("^"+t.replace(/([\[\]\?\(\)\\\\$\^\*\.|])/g,"\\$1").replace(/\+/g,"[^/]+").replace(/\/#$/,"(\/.*)?")+"$");
                                if (re.test(msg.topic)) {
                                    var subscribers = subscriptions[t];
                                    if (subscribers) {
                                        for (var i=0;i<subscribers.length;i++) {
                                            subscribers[i](msg.topic,msg.data);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        };
        ws.onclose = function() {
            connected = false;
            if (!active) {
                return;
            }
            if (clearErrorTimer) {
                clearTimeout(clearErrorTimer);
                clearErrorTimer = null;
            }
            reconnectAttempts++;
            if (reconnectAttempts < 10) {
                setTimeout(connectWS,1000);
                if (reconnectAttempts > 5 && errornotification == null) {
                    errornotification = RED.notify(RED._("notification.errors.lostConnection"),"error",true);
                }
            } else if (reconnectAttempts < 20) {
                setTimeout(connectWS,2000);
            } else {
                connectCountdown = 60;
                connectCountdownTimer = setInterval(function() {
                    connectCountdown--;
                    if (connectCountdown === 0) {
                        errornotification.update(RED._("notification.errors.lostConnection"));
                        clearInterval(connectCountdownTimer);
                        connectWS();
                    } else {
                        var msg = RED._("notification.errors.lostConnectionReconnect",{time: connectCountdown})+' <a href="#">'+ RED._("notification.errors.lostConnectionTry")+'</a>';
                        errornotification.update(msg,{silent:true});
                        $(errornotification).find("a").on("click", function(e) {
                            e.preventDefault();
                            errornotification.update(RED._("notification.errors.lostConnection"),{silent:true});
                            clearInterval(connectCountdownTimer);
                            connectWS();
                        })
                    }
                },1000);
            }

        }
    }

    function subscribe(topic,callback) {
        if (subscriptions[topic] == null) {
            subscriptions[topic] = [];
        }
        subscriptions[topic].push(callback);
        if (ws && ws.readyState == 1) {
            ws.send(JSON.stringify({subscribe:topic}));
        }
    }

    function unsubscribe(topic,callback) {
        if (subscriptions[topic]) {
            for (var i=0;i<subscriptions[topic].length;i++) {
                if (subscriptions[topic][i] === callback) {
                    subscriptions[topic].splice(i,1);
                    break;
                }
            }
            if (subscriptions[topic].length === 0) {
                delete subscriptions[topic];
            }
        }
    }

    /**
     * Publish a message to the runtime over the existing comms connection.
     * @param {String} topic - the topic to publish to
     * @param {Object} data - the message payload
     */
    function publish(topic,data) {
        if (ws && ws.readyState == 1) {
            ws.send(JSON.stringify({topic:topic,data:data}));
        }
    }

    function getSession() {
        return session;
    }

    function isConnected() {
        return connected && ws && ws.readyState == 1;
    }

    /**
     * Re-authenticate the current connection using the stored auth token.
     * Called after the user logs in without refreshing the page.
     */
    function reauthenticate() {
        var auth_tokens = RED.settings.get("auth-tokens");
        if (ws && ws.readyState == 1 && auth_tokens) {
            ws.send(JSON.stringify({auth:auth_tokens.access_token}));
        }
    }

    /**
     * Notify listeners that the user has logged out, then close the
     * connection. The onclose handler reconnects anonymously.
     */
    function logout() {
        notifyLogout();
        // Flag so an auth:fail caused by revoking the current token does
        // not trigger the login dialog; then close so we reconnect anonymously.
        loggingOut = true;
        if (ws) {
            try {
                ws.close();
            } catch(err) {}
        }
    }

    /**
     * Register a callback for when the comms connection is established
     * and ready to use.
     * @param {Function} callback - called with the session id
     * @return {Function} the callback, so it can later be removed
     */
    function addConnectionOpenedHandler(callback) {
        connectionOpenedHandlers.push(callback);
        if (isConnected()) {
            try {
                callback(session);
            } catch(err) {
                console.warn(err);
            }
        }
        return callback;
    }

    function removeConnectionOpenedHandler(callback) {
        for (var i=0;i<connectionOpenedHandlers.length;i++) {
            if (connectionOpenedHandlers[i] === callback) {
                connectionOpenedHandlers.splice(i,1);
                break;
            }
        }
    }

    /**
     * Register a callback for when the user logs out of the editor.
     * @param {Function} callback
     * @return {Function} the callback, so it can later be removed
     */
    function addLogoutHandler(callback) {
        logoutHandlers.push(callback);
        return callback;
    }

    function removeLogoutHandler(callback) {
        for (var i=0;i<logoutHandlers.length;i++) {
            if (logoutHandlers[i] === callback) {
                logoutHandlers.splice(i,1);
                break;
            }
        }
    }

    return {
        connect: connectWS,
        subscribe: subscribe,
        unsubscribe:unsubscribe,
        publish: publish,
        getSession: getSession,
        isConnected: isConnected,
        reauthenticate: reauthenticate,
        logout: logout,
        addConnectionOpenedHandler: addConnectionOpenedHandler,
        removeConnectionOpenedHandler: removeConnectionOpenedHandler,
        addLogoutHandler: addLogoutHandler,
        removeLogoutHandler: removeLogoutHandler
    }
})();
